# Simple approach: find all emit_progress\( and add None before the closing \);
import re

# Pattern to match emit_progress calls
def add_none_to_emit\(match\):
    call = match.group\(0\)
    # Check if it already has 10 parameters \(ends with None,\\n    \);\)
    if call.rstrip\(\).endswith\('None,\\n    \);'\) or call.rstrip\(\).endswith\('None,\\n        \);'\):
        return call
    # Find the last \); and insert None, before it
    lines = call.split\('\\n'\)
    # Find the line with \);
    for i in range\(len\(lines\) - 1, -1, -1\):
        if lines[i].strip\(\) == '\);':
            # Insert None, before this line with proper indentation
            indent = len\(lines[i]\) - len\(lines[i].lstrip\(\)\)
            lines.insert\(i, ' ' * indent + 'None,'\)
            break
    return '\\n'.join\(lines\)

# Match emit_progress\( ... \);
pattern = r'emit_progress\\\([^;]+\\\);'
content = re.sub\(pattern, add_none_to_emit, content, flags=re.DOTALL\)

